import { Timeseries } from '../../../core/types/timeseries.js';
import { PointsDisplay, GapPolicy } from '../../types/timeseries-props.js';
import { TimeseriesChartVisualProps } from '../../types/timeseries.js';

/** Props for the TimeseriesChart.Line slot component*/
export interface TimeseriesChartLineProps extends TimeseriesChartVisualProps {
  /** The series data passed to the line */
  data: Timeseries;
  /** Defines how gaps are handled (connect vs. gap) */
  gapPolicy?: GapPolicy;
  /** Whether to show data points always, never, or depending on a width-based threshold amount */
  pointsDisplay?: PointsDisplay;
}

export const Line = (props: TimeseriesChartLineProps) => null;

Line['displayName'] = 'TimeseriesChart.Line';
